// ── VALUE OBJECT: Money ──
class Money {
  readonly #paise: number;                    // sab kuch paise mein (float se bachne ke liye)

  private constructor(paise: number) {
    if (!Number.isInteger(paise)) throw new Error("Paise poora number hona chahiye");
    if (paise < 0) throw new Error("Money negative nahi ho sakti");
    this.#paise = paise;
  }

  static rupees(r: number): Money { return new Money(Math.round(r * 100)); }
  static zero(): Money { return new Money(0); }

  // IMMUTABLE: badalne wali har method NAYA Money deti hai
  plus(other: Money): Money  { return new Money(this.#paise + other.#paise); }
  times(n: number): Money    { return new Money(Math.round(this.#paise * n)); }

  minus(other: Money): Money {
    if (other.#paise > this.#paise) throw new Error("Itna paisa nahi hai");
    return new Money(this.#paise - other.#paise);
  }

  // VALUE se pehchaan -- id se nahi
  equals(other: Money): boolean { return this.#paise === other.#paise; }

  get rupees(): number { return this.#paise / 100; }
  toString(): string { return `₹${this.rupees.toFixed(2)}`; }
}

