// FCFS: order hi kaam ki baat hai.
function fcfs(procs) {
  return procs.slice().sort((a, b) => a.arrival - b.arrival);
}

// SJF: chhota (duration) pehle.
function sjf(procs) {
  return procs.slice().sort((a, b) => a.duration - b.duration);
}

