// 3. previous value
function usePrevious<T>(v: T) {
  const ref = useRef<T>();
  useEffect(() => { ref.current = v; });
  return ref.current;
}

// 4. latest value -- stale closure se bachne ke liye
const cbRef = useRef(onSave);
useEffect(() => { cbRef.current = onSave; });
useEffect(() => {
  const id = setInterval(() => cbRef.current(), 1000);  // hamesha latest
  return () => clearInterval(id);
}, []);   // deps khali rakh sakte ho

