type State = { table?: string; where?: string; fields?: string[] };

class Query<S extends State = {}> {
  #q: State = {};

  from<T extends string>(t: T): Query<S & { table: T }> {
    this.#q.table = t;
    return this as any;
  }

  where(w: string): Query<S & { where: string }> {
    this.#q.where = w;
    return this as any;
  }

  // execute sirf tab jab table set ho
  execute(this: Query<{ table: string }>): Promise<unknown[]> {
    return db.run(this.#q);
  }
}

